function clear(node) {
  while (node && node.firstChild) node.removeChild(node.firstChild);
}
function addText(node, tag, text) {
  const child = document.createElement(tag);
  child.textContent = text;
  node.appendChild(child);
  return child;
}
function labelFor(key) {
  const labels = {
    key_len: "Key Length",
    host_len: "Host Length",
    port: "Port",
    interval_weight: "Interval Weight",
    offline_depth: "Offline Depth",
    key_segments: "Key Segments"
  };
  return labels[key] || key;
}
function renderWorkspaceInfo(output, stats) {
  clear(output);
  const items = [
    ["key_len", String(stats.chars || 0)],
    ["host_len", String(stats.words || 0)],
    ["interval", String(stats.lines || 0)],
    ["interval_weight", String(stats.headings || 0)],
    ["offline_depth", String(stats.lists || 0)],
    ["key_segments", String(stats.fences || 0)]
  ];
  for (const [key, val] of items) {
    addText(output, "p", labelFor(key) + ": " + val);
  }
}
function renderScopeInfo(node, stats, offlineMode) {
  clear(node);
  if (!offlineMode) {
    node.textContent = "Offline: idle";
    return;
  }
  node.textContent = "Offline: active";
}
function q0(ctx = {}) {
  const output = document.querySelector("#workspacePanel");
  const scopePanel = document.querySelector("#scopePanel");
  const stats = ctx.stats || {};
  if (output) renderWorkspaceInfo(output, stats);
  if (scopePanel) renderScopeInfo(scopePanel, stats, Boolean(ctx.offlineMode));
  return ctx;
}
